/*
 * A041961  Denominators of continued fraction convergents to sqrt(503).
 * https://oeis.org/A041961
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, frac, easy
 * Formula:   a(n) is the denominator of the nth convergent to sqrt(503). The
 *            partial quotients of the continued fraction are generated by the
 *            standard recurrence m_{k+1} = d_k * a_k - m_k d_{k+1} = (503 -
 *            m_{k+1}^2) / d_k a_{k+1} = floor( (22 + m_{k+1}) / d_{k+1} ) .
 *            The first denominator is q_0 = 1 and the r...
 * Range:     u8 n <= 5, u16 n <= 8, u32 n <= 16, u64 n <= 33, u128 n <= 67,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#pragma once
#include <stdlib.h>

/* seq_t and idx_t are supplied by the build system.  */
seq_t a(idx_t n)
{
    /* static cache of pre‑computed terms */
    static seq_t *cache = NULL;
    static idx_t cap   = 0;   /* allocated size of cache */
    static idx_t sz    = 0;   /* number of terms stored (>=1) */

    /* static state for continued fraction generation */
    static idx_t m = 0;            /* m_k */
    static idx_t d = 1;            /* d_k */
    static idx_t a_coeff = 22;     /* a_k (starts with a_0) */
    static seq_t q_nm2 = (seq_t)0; /* q_{k-1}  (q_{-1}) */
    static seq_t q_nm1 = (seq_t)1; /* q_k      (q_0) */

    const idx_t disc = 503;   /* discriminant (sqrt(503)) */
    const idx_t a0    = 22;   /* integer part of sqrt(503) */

    /* initialise cache on the first call */
    if (sz == 0) {
        cap = 16;                     /* arbitrary initial capacity */
        cache = (seq_t *)calloc(cap, sizeof(seq_t));
        if (!cache) return (seq_t)0;  /* allocation failure: return 0 */
        cache[0] = (seq_t)1;          /* a(0) = 1 */
        sz = 1;
    }

    /* extend cache up to requested index n */
    if (n >= sz) {
        for (idx_t i = sz; i <= n; ++i) {
            /* generate next partial quotient a_{i} */
            idx_t m_next = d * a_coeff - m;
            idx_t d_next = (disc - m_next * m_next) / d;
            idx_t a_next = (a0 + m_next) / d_next;

            /* compute new denominator */
            seq_t a_next_seq = (seq_t)a_next;
            seq_t q_new = a_next_seq * q_nm1 + q_nm2;

            /* grow cache if necessary */
            if (sz == cap) {
                cap *= 2;
                seq_t *tmp = (seq_t *)realloc(cache, cap * sizeof(seq_t));
                if (!tmp) return (seq_t)0; /* allocation failure */
                cache = tmp;
            }
            cache[sz] = q_new;
            ++sz;

            /* shift window for next recurrence step */
            q_nm2 = q_nm1;
            q_nm1 = q_new;
            /* update CF state for next iteration */
            m = m_next;
            d = d_next;
            a_coeff = a_next;
        }
    }

    return cache[n];
}
